def family_init(ctx):
    """The reference signal, then the same signal shifted `lag` bars forward.

    Entry lag is normally an accident of latency. Here it is the parameter:
    an edge that survives an eight-bar delay is a different animal from one
    that lives entirely in the first bar, and only sweeping L tells them apart.
    """
    bars = ctx.bars
    m = len(bars)
    n = max(2, int(ctx.p.don_n))
    lag = max(0, int(ctx.p.lag))
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]
    c = [float(b["c"]) for b in bars]

    fire = [0] * m
    for i in range(n, m):
        hi = h[i - n]
        lo = l[i - n]
        for j in range(i - n + 1, i):
            if h[j] > hi:
                hi = h[j]
            if l[j] < lo:
                lo = l[j]
        if c[i] > hi:
            fire[i] = 1
        elif c[i] < lo:
            fire[i] = -1

    out = [0] * m
    for i in range(m):
        j = i - lag
        if j < 0:
            continue
        s = fire[j]
        if s == 0:
            continue
        bad = False
        for k in range(j + 1, i + 1):
            if fire[k] == -s:
                bad = True
                break
        if not bad:
            out[i] = s
    ctx.sg = ctx.series(out, "delayed_breakout")


def signal(ctx, i):
    s = ctx.sg[i]
    if s is None:
        return 0
    return int(s)
